PAYLOAD={'device_calls.py': '"""Vinculo revogavel do aparelho; sessoes temporarias restritas a uma chamada."""\nimport hashlib,hmac,secrets,sqlite3,time,threading,json\nSCOPED={}\nLOCK=threading.RLock()\nPREFIX=\'/api/device-calls/\'\n\ndef db(server):\n path=server.DATA/\'call-devices.sqlite\'\n c=sqlite3.connect(path,timeout=10);c.row_factory=sqlite3.Row\n import os\n os.chmod(path,0o600)\n c.execute("CREATE TABLE IF NOT EXISTS devices(token TEXT PRIMARY KEY,uid TEXT NOT NULL,fingerprint TEXT NOT NULL,expires REAL NOT NULL,created REAL NOT NULL,ignored TEXT NOT NULL DEFAULT \'[]\')")\n return c\n\ndef digest(token):return hashlib.sha256(token.encode()).hexdigest()\n\ndef scoped_room(token):\n with LOCK:return SCOPED.get(token)\n\ndef guard(server,token,user):\n scoped=scoped_room(token)\n if not scoped:return user\n identity=server.call_identity(user)\n if any(c[\'id\']==scoped for c in server.CALLS.list(identity)[\'calls\']):\n  with server.SESSION_LOCK:server.SESSIONS[token]=(user[\'id\'],time.time()+90)\n  return {**user,\'call_only\':True,\'call_room\':scoped}\n with server.SESSION_LOCK:server.SESSIONS.pop(token,None)\n with LOCK:SCOPED.pop(token,None)\n return None\n\ndef route(handler,server,user,path):\n if not path.startswith(PREFIX):return False\n action=path[len(PREFIX):];data=handler.body()\n def reply(status=200,**obj):handler.reply(status,obj);return True\n if action==\'logout\':\n  token=handler.session_token()\n  with server.SESSION_LOCK:server.SESSIONS.pop(token,None)\n  with LOCK:SCOPED.pop(token,None)\n  handler.send_response(200);handler.headers_common();handler.send_header(\'Set-Cookie\',\'fsj_session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict\');handler.send_header(\'Content-Length\',\'2\');handler.end_headers();handler.wfile.write(b\'{}\');return True\n now=time.time()\n if action==\'bind\':\n  if not user or user.get(\'call_only\'):return reply(403,error=\'Entre com login e senha para vincular o aparelho.\')\n  old=str(data.get(\'previous\',\'\'));token=secrets.token_urlsafe(48)\n  with server.db() as main:row=main.execute(\'SELECT hash FROM users WHERE id=?\',(user[\'id\'],)).fetchone()\n  c=db(server)\n  try:\n   with c:\n    c.execute(\'DELETE FROM devices WHERE expires<?\',(now,))\n    if old:c.execute(\'DELETE FROM devices WHERE token=? AND uid=?\',(digest(old),user[\'id\']))\n    rows=c.execute(\'SELECT token FROM devices WHERE uid=? ORDER BY created DESC\',(user[\'id\'],)).fetchall()\n    for r in rows[4:]:c.execute(\'DELETE FROM devices WHERE token=?\',(r[\'token\'],))\n    c.execute(\'INSERT INTO devices(token,uid,fingerprint,expires,created) VALUES(?,?,?,?,?)\',(digest(token),user[\'id\'],row[\'hash\'],now+30*86400,now))\n  finally:c.close()\n  return reply(token=token,expires_in=30*86400)\n bearer=handler.headers.get(\'Authorization\',\'\')\n if not bearer.startswith(\'Bearer \') or len(bearer)>200:return reply(401,error=\'Vinculo indisponivel. Entre novamente.\')\n token=bearer[7:];c=db(server)\n try:device=c.execute(\'SELECT * FROM devices WHERE token=? AND expires>?\',(digest(token),now)).fetchone()\n finally:c.close()\n if not device:return reply(401,error=\'Vinculo expirado. Entre novamente.\')\n with server.db() as main:account=main.execute("SELECT * FROM users WHERE id=? AND status=\'active\'",(device[\'uid\'],)).fetchone()\n if not account or not hmac.compare_digest(account[\'hash\'],device[\'fingerprint\']):return reply(401,error=\'Conta alterada. Entre novamente.\')\n account=dict(account)\n if not server.mirror_account_allowed(account):return reply(403,error=\'Acesso bloqueado.\')\n identity=server.call_identity(account)\n if action==\'unbind\':\n  c=db(server)\n  try:\n   with c:c.execute(\'DELETE FROM devices WHERE token=?\',(digest(token),))\n  finally:c.close()\n  return reply(ok=True)\n calls=server.CALLS.list(identity)[\'calls\']\n ignored=json.loads(device[\'ignored\'])\n if action==\'dismiss\':\n  room=str(data.get(\'room\',\'\'))\n  if room not in [c[\'id\'] for c in calls]:return reply(410,error=\'Chamada encerrada.\')\n  c=db(server)\n  try:\n   with c:c.execute(\'UPDATE devices SET ignored=? WHERE token=?\',(json.dumps((ignored+[room])[-20:]),digest(token)))\n  finally:c.close()\n  return reply(ok=True)\n calls=[c for c in calls if c[\'id\'] not in ignored]\n if action==\'poll\':return reply(self_id=identity[\'id\'],calls=calls)\n if action==\'answer\':\n  room=str(data.get(\'room\',\'\'))\n  call=next((x for x in calls if x[\'id\']==room),None)\n  if not call or call[\'owner\']==identity[\'id\'] or not any(m[\'id\']==call[\'owner\'] and m[\'present\'] for m in call[\'members\']):return reply(410,error=\'Chamada encerrada.\')\n  session=secrets.token_urlsafe(32)\n  with server.SESSION_LOCK:\n   for key,(_,expires) in list(server.SESSIONS.items()):\n    if expires<now:\n     server.SESSIONS.pop(key,None)\n     with LOCK:SCOPED.pop(key,None)\n   server.SESSIONS[session]=(account[\'id\'],now+90)\n  with LOCK:SCOPED[session]=room\n  handler.send_response(200);handler.headers_common();handler.send_header(\'Set-Cookie\',\'fsj_session=\'+session+\'; Path=/; HttpOnly; Secure; SameSite=Strict\');handler.send_header(\'Content-Type\',\'application/json\');handler.send_header(\'Content-Length\',\'2\');handler.end_headers();handler.wfile.write(b\'{}\');return True\n return reply(404,error=\'Operacao indisponivel.\')\n', 'call.html': '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chamada FSJ</title><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/call-session.css"><header><img src="/logo.webp" alt="Fazenda Sao Jose"><div><strong>FSJ Reserva</strong><p>Chamada recebida</p></div></header><main><div id="content"><div id="activeCallBar" hidden><span id="activeCallLabel"></span><button id="activeCallJoin" type="button">Entrar</button><button id="activeCallStop" type="button">Sair</button></div><section id="callPanel" class="card"><h1>Chamadas de vídeo</h1><p>Selecione pessoas, escolha voz ou vídeo e toque em Iniciar chamada.</p><p class="muted">O Proprietário pode iniciar uma gravação, sinalizada durante a chamada. Ao entrar, você concorda em participar nessas condições.</p><form id="callCreate" class="owner" hidden><label>Título da conversa<input id="callNewTitle" value="Conversa FSJ" maxlength="100" required></label><label>Tipo de chamada<select id="callMode"><option value="video">Vídeo e voz</option><option value="audio">Somente voz</option></select></label><div id="callInviteActions"><fieldset><legend>Convidar até três participantes</legend><div id="callParticipants"></div></fieldset><button id="callStart" type="submit">Iniciar chamada</button></div><button id="callSaveDraft" type="button">Salvar preparação</button></form><button id="callRefresh" type="button">Atualizar convites e participantes</button><div id="callInvites" aria-live="polite"></div><div id="callLive" hidden><h2 id="callTitleLive"></h2><p id="recordNotice" class="record-notice" hidden>● Gravação em andamento pelo Proprietário</p><div id="callGrid" class="call-grid"></div><button id="callPlayAudio" type="button" hidden>Ativar áudio e vídeo</button><div class="call-controls"><button id="callMic" type="button">Desligar microfone</button><button id="callCamera" type="button">Desligar câmera</button><button id="callLeave" type="button">Sair da chamada</button><button id="callEnd" type="button" class="danger" hidden>Encerrar para todos</button><button id="callRecord" type="button" hidden>Gravar conversa</button><button id="callStopRecord" type="button" hidden>Parar gravação</button></div></div><form id="recordSave" hidden><h2>Salvar gravação</h2><label>Título do vídeo<input id="recordName" maxlength="160" required></label><label class="check"><input id="recordShare" type="checkbox">Permitir consulta aos participantes convidados que continuam ativos</label><p class="muted">Sem marcar: somente o Proprietário poderá assistir. Apenas o Proprietário pode baixar. Até cinco minutos por gravação.</p><button>Salvar gravação na videoteca</button><button id="recordDiscard" type="button" class="danger">Descartar gravação</button></form><canvas id="callCanvas" width="960" height="540" hidden></canvas><p id="callStatus" role="status" aria-live="polite"></p></section></div><p id="status" role="status"></p></main><script src="/calls.js"></script><script src="/call-session.js"></script></html>', 'call-session.js': "/* FSJ_CALL_ONLY_ANDROID12 */\n;(async()=>{\ntry{\nconst response=await fetch('/api/me',{cache:'no-store'});const user=await response.json();if(!response.ok||!user.call_only)throw Error('Chamada encerrada.');\nwindow.fsjCurrentUser=user;\ndocument.dispatchEvent(new CustomEvent('fsj:session',{detail:user}));\nlet attempts=0;\nconst start=()=>{if(!window.FSJAndroid)return;const id=FSJAndroid.pendingAnswer();if(id){document.dispatchEvent(new CustomEvent('fsj:answer-call',{detail:{id}}));return;}if(++attempts<20)setTimeout(start,200);};\nsetTimeout(start,150);\n}catch(error){document.getElementById('status').textContent=error.message;setTimeout(()=>window.FSJAndroid?.callEnded(),2000);}\n})();", 'call-session.css': '#content{overflow:auto}#callPanel{overflow:auto!important}#callCreate,#callSaveDraft,#callRefresh,#callInvites,#callRecord,#callStopRecord,#recordSave,#fsjCallSoundBar{display:none!important}#callLive:not([hidden]){max-height:none;overflow:visible}#callPanel:not(:has(#callLive:not([hidden])))>p{display:none}#callStatus,#status{font-size:14px;overflow:visible;max-height:none}'}
APK_SHA='a5f2197ca98a7dd1b2423a572cf8cd6db7bf15a3716114d21900dc292b83ca22'
APK_URL='https://raw.githubusercontent.com/urbanopos/Assistente.FSJ/main/downloads/FSJ-Reserva-Local-14.apk'
LOGIN_JS='/* FSJ_SAVED_LOGIN_ROW_V14 */\n;(()=>{\nconst el=id=>document.getElementById(id),form=el(\'loginForm\'),password=el(\'password\'),name=el(\'name\');\nif(!form||!password||!name||el(\'fsjLoginActions\'))return;\nlet remember=el(\'rememberLogin\'),label=el(\'rememberLoginLabel\');\nif(!remember){remember=document.createElement(\'input\');remember.type=\'checkbox\';remember.id=\'rememberLogin\';}\nif(!label){label=document.createElement(\'label\');label.id=\'rememberLoginLabel\';}\nlabel.replaceChildren(remember,document.createTextNode(\'Salvar senha\'));label.hidden=false;label.className=\'check\';\nlet show=[...form.querySelectorAll(\'button\')].find(b=>/mostrar senha|ocultar senha/i.test(b.textContent));\nif(!show){show=document.createElement(\'button\');show.type=\'button\';show.textContent=\'Mostrar senha\';show.onclick=()=>{const on=password.type===\'password\';password.type=on?\'text\':\'password\';show.textContent=on?\'Ocultar senha\':\'Mostrar senha\';show.setAttribute(\'aria-pressed\',String(on));};}\nshow.id=\'fsjShowLoginPassword\';show.removeAttribute(\'style\');\nconst submit=form.querySelector(\'button[type="submit"],button:not([type])\');\nif(!submit)return;submit.type=\'submit\';submit.id=\'fsjLoginSubmit\';\nconst row=document.createElement(\'div\');row.id=\'fsjLoginActions\';row.append(label,show,submit);form.append(row);\nlet pending=null;\nfunction native(){return !!window.FSJAndroid?.savedLogin&&!!window.FSJAndroid?.saveLogin;}\ntry{remember.checked=localStorage.getItem(\'fsj_remember_choice\')===\'1\';}catch{}\nremember.addEventListener(\'change\',()=>{\ntry{localStorage.setItem(\'fsj_remember_choice\',remember.checked?\'1\':\'0\');}catch{}\nif(!remember.checked&&native())FSJAndroid.saveLogin(\'\',\'\',false);\n});\nform.addEventListener(\'submit\',()=>{pending={name:name.value,password:password.value,remember:remember.checked};},true);\ndocument.addEventListener(\'fsj:session\',async()=>{\nif(!pending)return;const saved=pending;pending=null;\ntry{\nif(native()){FSJAndroid.saveLogin(saved.name,saved.password,saved.remember);return;}\nif(saved.remember&&window.PasswordCredential&&navigator.credentials?.store){await navigator.credentials.store(new PasswordCredential({id:saved.name,password:saved.password,name:saved.name}));}else if(saved.remember){throw Error(\'Gerenciador indisponivel\');}\n}catch{const status=el(\'status\');if(status)status.textContent=\'Acesso realizado. O navegador nao conseguiu salvar a senha; use seu gerenciador de senhas ou o aplicativo Android atualizado.\';}\n});\n// O bridge Android e adicionado antes da pagina; a verificacao de origem e feita no nativo.\nfunction restore(){if(!native())return false;try{const saved=JSON.parse(FSJAndroid.savedLogin());if(saved.name&&saved.password){name.value=saved.name;password.value=saved.password;remember.checked=true;}return true;}catch{return false;}}\nif(!restore())document.addEventListener(\'DOMContentLoaded\',restore,{once:true});\n})();\n'
LOGIN_CSS='/* FSJ_SAVED_LOGIN_ROW_V14 */\n#login #fsjLoginActions{display:flex;align-items:center;justify-content:space-between;gap:5px;flex-wrap:nowrap;margin:7px 0}\n#login #fsjLoginActions #rememberLoginLabel{display:flex!important;align-items:center;gap:4px;margin:0;font-size:12px;line-height:1.15;flex:1;min-width:0}\n#login #fsjLoginActions #rememberLogin{width:18px;height:18px;margin:0;padding:0;flex:none}\n#login #fsjLoginActions button{display:block;width:auto;white-space:nowrap;font-size:12px;min-height:36px;padding:7px 8px;margin:0;flex:none}\n@media(max-width:340px){#login #fsjLoginActions{gap:3px}#login #fsjLoginActions button{font-size:11px;padding:6px}#login #fsjLoginActions #rememberLoginLabel{font-size:11px}}\n'
def patch(text):
 if 'FSJ_DEVICE_CALLS_V12' in text:return text
 text='# FSJ_DEVICE_CALLS_V12\n'+text
 anchor="  path=urlparse(self.path).path; user=self.user()\n"
 assert text.count(anchor)==1,'Entrada de servidor diferente.'
 text=text.replace(anchor,anchor+"  if path.startswith('/api/device-calls/'):\n   import device_calls,sys\n   return device_calls.route(self,sys.modules[__name__],user,path)\n  if user and user.get('call_only') and path not in ('/api/calls/join','/api/calls/poll','/api/calls/signal','/api/calls/leave','/api/calls/end'):\n   return self.reply(403,{'error':'Sessao restrita a chamada.'})\n",1)
 a=text.index(' def user(self):');b=text.index(' def body(self):',a)
 part=text[a:b];old='  return user if user and mirror_account_allowed(user) else None'
 assert part.count(old)==1,'Autenticacao diferente.'
 part=part.replace(old,"  if user and mirror_account_allowed(user):\n   import device_calls,sys\n   return device_calls.guard(sys.modules[__name__],token,user)\n  return None",1);text=text[:a]+part+text[b:]
 old="   try: return self.reply(obj=CALLS.post(call_identity(user),path.rsplit('/',1)[-1],self.body()))"
 assert text.count(old)==1,'Controle de chamadas diferente.'
 text=text.replace(old,"   try:\n    data=self.body()\n    if user.get('call_room') and data.get('room')!=user['call_room']:return self.reply(403,{'error':'Outra chamada nao autorizada.'})\n    return self.reply(obj=CALLS.post(call_identity(user),path.rsplit('/',1)[-1],data))",1)
 old="  if path in ('/','/app.js','/calls.js','/style.css','/logo.webp'):"
 assert text.count(old)==1,'Arquivos estaticos diferentes.'
 text=text.replace(old,"  if path in ('/','/app.js','/calls.js','/style.css','/logo.webp','/call.html','/call-session.js','/call-session.css'):",1)
 text=text.replace("'.webp':'image/webp'}", "'.webp':'image/webp'}",1)
 old="  if path=='/api/mirror':return self.reply(obj=mirror_view(user))"
 assert text.count(old)==1,'Consulta diferente.'
 text=text.replace(old,"  if user.get('call_only') and path not in ('/api/me','/api/calls'):return self.reply(403,{'error':'Sessao restrita a chamada.'})\n"+old,1)
 old="   identity=call_identity(user);return self.reply(obj={**CALLS.list(identity),'self_id':identity['id']})"
 assert text.count(old)==1,'Lista de chamadas diferente.'
 text=text.replace(old,"   identity=call_identity(user);data=CALLS.list(identity)\n   if user.get('call_room'):data['calls']=[c for c in data['calls'] if c['id']==user['call_room']]\n   return self.reply(obj={**data,'self_id':identity['id']})",1)
 compile(text,'server.py','exec');return text
def install(root,restart=True,apk=None):
 root=pathlib.Path(root).resolve();server=root/'server.py';calls=root/'static/calls.js'
 original=server.read_text();new=patch(original)
 js=calls.read_text();anchor='if(user)listCalls();}';replacement="if(user)listCalls();if(old)document.dispatchEvent(new Event('fsj:call-ended'));}"
 if 'fsj:call-ended' not in js:
  assert js.count(anchor)==1,'Finalizacao diferente do esperado.'
  js=js.replace(anchor,replacement,1)
 if apk is None:
  with urllib.request.urlopen(APK_URL,timeout=90) as response:apk=response.read(5000000)
  assert hashlib.sha256(apk).hexdigest()==APK_SHA,'APK nao validado. Nada alterado.'
 changes={server:new.encode(),calls:js.encode(),root/'device_calls.py':PAYLOAD['device_calls.py'].encode()}
 for name in ['call.html','call-session.js','call-session.css']:changes[root/'static'/name]=PAYLOAD[name].encode()
 loginapp=root/'static/app.js'
 logintext=loginapp.read_text()
 if 'FSJ_SAVED_LOGIN_ROW_V14' not in logintext:logintext+='\n'+LOGIN_JS
 changes[loginapp]=logintext.encode()
 html=root/'static/index.html'
 if html.exists():
  markup=html.read_text().replace('Android · instalar versao 13','Android · instalar versao 14').replace('android?versao=13','android?versao=14').replace('Android · instalar versao 12','Android · instalar versao 14').replace('android?versao=12','android?versao=14').replace('Android · instalar aplicativo','Android · instalar versao 14').replace('Android · baixar aplicativo','Android · instalar versao 14').replace('href="/baixar/android"','href="/baixar/android?versao=14"')
  changes[html]=markup.encode()
 if apk:
  changes[root/'releases/FSJ-Reserva-VM-V001-Simples.apk']=apk
  version=json.loads((root/'version.json').read_text());assert version.get('android_version',0)<=14,'Android mais novo instalado.'
  version['android_version']=14;changes[root/'version.json']=json.dumps(version).encode()
 style=root/'static/style.css'
 stylesheet=style.read_text()
 if 'FSJ_SAVED_LOGIN_ROW_V14' not in stylesheet:stylesheet+='\n'+LOGIN_CSS
 changes[style]=stylesheet.encode()
 backup=root/'backups'/('android-senha14-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'));backup.mkdir(parents=True)
 existed={p:p.exists() for p in changes}
 for p in changes:
  if p.exists():
   dest=backup/p.relative_to(root);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
 try:
  for p,value in changes.items():
   p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_name(p.name+'.android12.tmp');tmp.write_bytes(value)
   if p.exists():shutil.copymode(p,tmp)
   os.replace(tmp,p)
  if restart:subprocess.run(['systemctl','--user','restart','fsj-reserva.service'],check=True)
 except BaseException:
  for p in changes:
   if existed[p]:shutil.copy2(backup/p.relative_to(root),p)
   else:p.unlink(missing_ok=True)
  if restart:subprocess.run(['systemctl','--user','restart','fsj-reserva.service'])
  raise
 print('INSTALADO NA VM: Reserva Android versao 14, salvar senha e controles em uma linha; chamadas e atualizacao automatica preservadas.')
 print('Backup:',backup)
 print('Feche e reabra o Reserva nos dois celulares. Confirme a atualizacao oferecida pelo Android. Marque Salvar senha na tela de entrada.')
 print('Contas, senhas, recuperacao por WhatsApp e rotina das 7h preservados. Teste real nos celulares ainda necessario.')
if __name__=='__main__':install(sys.argv[1] if len(sys.argv)>1 else str(pathlib.Path.home()/'fsj-video-v001'))
